-- Вкладки чек-листов для Альф: хранителей и рейнджеров (пункты — заготовка, правятся в «Править чек-листы»)
alter table public.shift_lists drop constraint if exists shift_lists_kind_check;
alter table public.shift_lists add constraint shift_lists_kind_check check(kind in('open','close','alpha_k','alpha_r'));
insert into public.shift_lists(title,kind,zone,items,sort)
select v.t,v.k,null,v.i,v.s from (values
 ('Проверка локаций','alpha_k',array['Лес: Веревочный лагерь, Золото, Гольф, Лучный тир','Вода: Аквазона Кит, Визги-брызги','Горы: Шахта, Карусель, Джипы','Воздух: Кон-Тики, Плющ, Данделион','Купол: Сухие горки, Студия, Квесты и роботы, Терраса','Замечания записаны в «Смене» или «Поломках»'],101),
 ('Роспись журналов','alpha_k',array['Журналы открытия подписаны','Журналы закрытия подписаны','Журнал происшествий просмотрен','Журнал инструктажей проверен'],102),
 ('Купол · открытие','alpha_k',array['Купол осмотрен перед открытием','Сухие горки, Студия, Квесты и роботы, Терраса готовы','Персонал на местах','Купол открыт для гостей'],103),
 ('Купол · закрытие','alpha_k',array['Гости покинули Купол','Сухие горки, Студия, Квесты и роботы, Терраса закрыты','Оборудование выключено','Купол закрыт'],104),
 ('Открытие Метрополиса','alpha_r',array['Метрополис осмотрен','Свет и техника включены','Персонал на местах','Метрополис открыт для гостей'],201),
 ('Проверка зон Метрополиса','alpha_r',array['VR-арена','Боулинг','Детский клуб','Бильярд','Кино'],202),
 ('Помощь в открытии зоны Леса','alpha_r',array['Связался(ась) с хранителем Леса','Помог(ла) осмотреть зону','Помог(ла) с оборудованием','Зона Леса открыта'],203)
) as v(t,k,i,s)
where not exists(select 1 from public.shift_lists where kind in('alpha_k','alpha_r') and title=v.t);

-- Алексюк Игорь — Владелец (права руководителя)
update public.roster set pre_role='manager', pre_position='Владелец' where full_name='Алексюк Игорь';
update public.profiles set position='Владелец' where id in(select profile_id from public.roster where full_name='Алексюк Игорь' and profile_id is not null);
